def fA(I):
    I=np.array(I); H,W=I.shape
    bg=int(Counter(I.flatten()).most_common(1)[0][0]); out=I.copy()
    K=[]
    for col in sorted({int(x) for x in I.flatten()}-{bg}):
        lab,n=label(I==col,structure=[[0,1,0],[1,1,1],[0,1,0]])
        for i in range(1,n+1):
            rs,c_=np.where(lab==i)
            s=len(rs); r0,r1,c0,c1=int(rs.min()),int(rs.max()),int(c_.min()),int(c_.max())
            if s==(r1-r0+1)*(c1-c0+1): K.append((col,(r0,r1,c0,c1)))
    for col,(r0,r1,c0,c1) in K:
        out[r0:r1+1,c0:c1+1]=col
    for r in range(H):
        for c in range(W):
            if int(I[r,c])!=bg and out[r,c]!=int(I[r,c]): pass
            # assign remaining non-bg cells: inside a rect bbox? then that color; else bg
            cc=None
            for col_,bb in K:
                r0,r1,c0,c1=bb
                if r0<=r<=r1 and c0<=c<=c1: cc=(r1-r0+1)*(c1-c0+1),col_
            if cc and (out[r,c]==bg or cc[1]!=out[r,c]): out[r,c]=cc[1]
    return out.tolist()

