import os,re,numpy as np,json
from collections import Counter
from scipy.ndimage import label

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(I, bg):
    H,W=I.shape
    out=[]
    cols={int(x) for x in I.flatten()}-{bg}
    for col in cols:
        lab,n=label(I==col,structure=[[0,1,0],[1,1,1],[0,1,0]])
        for i in range(1,n+1):
            rs,c_=np.where(lab==i)
            s=len(rs)
            r0,r1,c0,c1=int(rs.min()),int(rs.max()),int(c_.min()),int(c_.max())
            area=(r1-r0+1)*(c1-c0+1)
            is_rect = (s==area and s>=2)
            out.append({'col':col,'n':s,'r0':r0,'r1':r1,'c0':c0,'c1':c1,'rect':is_rect,'bbox_area':area})
    return out

def solve_vB(I):
    I=np.array(I); H,W=I.shape
    bg=int(Counter(I.flatten()).most_common(1)[0][0])
    cs=comps(I,bg)
    rects=[c for c in cs if c['rect']]
    cells={'rect':False,'col':None}
    for c in cs:
        if c['rect']:
            cells[(c['r0'],c['r1'],c['c0'],c['c1'])]=c
    O=np.zeros_like(I,dtype=int)
    for r in range(H):
        for c in range(W):
            v=int(I[r,c])
            if v==bg: continue
            # check if exact comp of this color matches its own rect
            key=None
            for cc in cs:
                if cc['col']==v:
                    key=(cc['r0'],cc['r1'],cc['c0'],cc['c1'])
                    break
            if key and cells[key]['rect']:
                O[r,c]=v
            else:
                # try containing rectangles
                contained=False
                best=None
                for (k0,k1,k2,k3),dc in cells.items():
                    if k0<=r<=k1 and k2<=c<=k3 and dc['rect'] and best is None or dc['col']>best is None or dc['col']>=best['col']:
                        pass
                # find rectangle containing this cell with largest area
                cands=[]
                for (k0,k1,k2,k3),dc in cells.items():
                    if dc['rect'] and k0<=r<=k1 and k2<=c<=k3:
                        cands.append(( (k1-k0)*(k3-k2), dc['col'] ))
                if cands:
                    _,cc=max(cands,key=lambda x:x[0])
                    O[r,c]=cc
                else:
                    O[r,c]=bg
    return O.tolist()

allb=True
for i in [1,2,3,4]:
    inp=G[f'Demo pair {i} input']; Opts=G[f'Demo pair {i} output']
    p=solve_vB(inp)
    bad=[(r,c,p[r][c],Opts[r][c]) for r in range(len(Opts)) for c in range(len(Opts[0])) if p[r][c]!=Opts[r][c]]
    print(i,len(bad),bad[:5])
    allb&=(not bad)
print('ALL OK' if allb else 'FAIL')
if allb: T=solve_vB(G['Test input']); print(json.dumps(T))

